from pathlib import Path
import base64
import json

import numpy as np
from PIL import Image

R = Path(__file__).resolve().parents[2]
O = R / 'renders/falaises_proches_metano_v2'
m = json.loads((O / 'manifest.json').read_text())
LAYERS = ['00_HERBE_NATIVE', '01_FACES_NATIVE', '02_RETOURS_NATIVE',
          '03_COURONNES_NATIVE', '04_PIEDS_NATIVE']


def uri(p):
    return 'data:image/png;base64,' + base64.b64encode(Path(p).read_bytes()).decode()


sea_idx = np.array(Image.open(O / 'commun/ocean/jour_00.png'))
pals = json.loads((O / 'commun/ocean/palettes.json').read_text())
data = {'manifest': m,
        'commun': {n: uri(O / 'commun' / (n + '.png')) for n in
                   ['01_ciel_jour', '02_ciel_nuit',
                    '05_nuages_wrap_jour', '06_nuages_wrap_nuit']},
        'sea': {'w': sea_idx.shape[1], 'h': sea_idx.shape[0],
                'idx': base64.b64encode(sea_idx.tobytes()).decode(),
                'pal': pals},
        'variants': {v['id']: {**v, 'layers': {
            n: uri(O / v['id'] / (n + '.png')) for n in LAYERS},
            'layers_n': {n: uri(O / v['id'] / (n + '_NUIT.png')) for n in LAYERS}}
            for v in m['variants']}}
h = '''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Falaises Métano V2 · natif Halcyon · mer 64ph · wrap 2200</title><style>*{box-sizing:border-box}body{margin:0;background:#101820;color:#e8f0f8;font:16px system-ui}header,main,footer{max-width:1260px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#bcc8d8;line-height:1.6}.tag{font-size:12px;letter-spacing:2px;color:#9fd0ff}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}select,button{padding:12px;border:1px solid #4a6a8a;border-radius:6px;background:#1d2c3e;color:#eef4fc}.layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px}canvas{display:block;width:100%;max-width:768px;image-rendering:pixelated;background:#0a1018}aside{background:#17222f;padding:18px;border-radius:8px}label{display:block;margin:12px 0;font-size:14px}a{color:#bcdcff}small{color:#93a5b8}footer{border-top:1px solid #2a3a4e}.anim{display:flex;gap:8px;align-items:center;margin:12px 0;font-size:14px;flex-wrap:wrap}.anim button{padding:8px 12px}input[type=range]{width:110px}@media(max-width:780px){.layout{grid-template-columns:1fr}}</style><header><div class="tag">MÉTANO / NATIF HALCYON / MER 64 PHASES / WRAP 2200</div><h1>Falaises latérales V2 · 100% pixels natifs</h1><p>Deux variantes reconstruites en modules natifs Métano Town (Herbe, Faces, Retours, Couronnes, Pieds), calque par calque. Mer réutilisée de l’océan V2 (64 phases jour/nuit), nuages réutilisés du strip COTEV2 (wrap 2200px à 12px/s). Nuit = filtre Abyss exact, une passe.</p></header><main><div class="toolbar"><select id="room"></select><button id="dn">🌙 Passer en nuit</button><button id="export">Exporter PNG affiché</button></div><div class="layout"><section><canvas id="view" width="768" height="512"></canvas><div class="anim"><button id="play">⏸ Pause</button><label style="margin:0">nuages <input type="range" id="speed" min="5" max="120" value="12"> <span id="spd">12px/s</span></label><span id="off"></span><span id="sea"></span></div><p id="status"></p></section><aside><b>Calques</b><div id="layers"></div><small>Ordre : ciel, nuages (wrap y=8), mer (64 phases × 50ms), herbe, faces, retours, couronnes, pieds. Période de wrap 2200px : boucle parfaite, raccord L==R vérifié à l’octet.</small></aside></div></main><footer><p>Sources : tuiles Métano Town d’Halcyon (commits épinglés, voir manifest), océan V2 (caps_terrasses_v3), strip COTEV2 (cote_v2). Terrains : 145 + 212 tampons natifs, alpha des masques V1 conservée à l’octet, vérification PASS.</p><small>Ni collisions ni test PMDO.</small></footer><script>const D=__DATA__,c=document.getElementById('view'),ctx=c.getContext('2d'),select=document.getElementById('room');let vid='cap_gauche',isNight=false,playing=true,off=0,last=0,speed=12;const IM={};function image(src){let im=new Image();im.src=src;return im}for(const [k,v]of Object.entries(D.commun))IM[k]=image(v);for(const [id,e]of Object.entries(D.variants)){for(const [k,v]of Object.entries(e.layers))IM[id+'_'+k]=image(v);for(const [k,v]of Object.entries(e.layers_n))IM[id+'_'+k+'_n']=image(v);let o=document.createElement('option');o.value=id;o.textContent=e.title;select.append(o)}const LAYERS=[['ciel','Ciel'],['nuages','Nuages (wrap)'],['mer','Mer (64 phases)'],['00_HERBE_NATIVE','Herbe native'],['01_FACES_NATIVE','Faces natives'],['02_RETOURS_NATIVE','Retours natifs'],['03_COURONNES_NATIVE','Couronnes natives'],['04_PIEDS_NATIVE','Pieds natifs']],vis={};for(const [k]of LAYERS)vis[k]=true;const root=document.getElementById('layers');for(const [k,t]of LAYERS){const l=document.createElement('label'),ch=document.createElement('input');ch.type='checkbox';ch.checked=true;ch.onchange=()=>vis[k]=ch.checked;l.append(ch,document.createTextNode(t));root.append(l)}select.onchange=()=>vid=select.value;document.getElementById('dn').onclick=e=>{isNight=!isNight;e.target.textContent=isNight?'☀️ Passer en jour':'🌙 Passer en nuit'};document.getElementById('export').onclick=()=>{let a=document.createElement('a');a.href=c.toDataURL();a.download=vid+(isNight?'_nuit':'_jour')+'.png';a.click()};document.getElementById('play').onclick=e=>{playing=!playing;e.target.textContent=playing?'⏸ Pause':'▶ Animer'};document.getElementById('speed').oninput=e=>{speed=+e.target.value;document.getElementById('spd').textContent=speed+'px/s'};const P=D.manifest.cloud_period,CY=D.manifest.cloud_y;const SE=D.sea,sw=SE.w,sh=SE.h,sidx=Uint8Array.from(atob(SE.idx),x=>x.charCodeAt(0)),seaCv=document.createElement('canvas');seaCv.width=sw;seaCv.height=sh;const sctx=seaCv.getContext('2d'),simg=sctx.createImageData(sw,sh);function seaFrame(f,mode){const pal=SE.pal[mode][f],d=simg.data;for(let i=0;i<sidx.length;i++){const o=i*4,p=sidx[i]*3;d[o]=pal[p];d[o+1]=pal[p+1];d[o+2]=pal[p+2];d[o+3]=255}sctx.putImageData(simg,0,0)}function draw(im,x,y){if(im.complete&&im.naturalWidth)ctx.drawImage(im,x,y)}let elapsed=0;function render(t){const dt=Math.min(100,t-(last||t));last=t;if(playing){off=(off+speed*dt/1000)%P;elapsed+=dt}const f=Math.floor(elapsed/50)%64;document.getElementById('off').textContent='nuages '+Math.round(off)+'px / '+P;document.getElementById('sea').textContent='mer phase '+f+' / 64';document.getElementById('status').textContent=D.variants[vid].title+(isNight?' · nuit':' · jour');ctx.clearRect(0,0,768,512);if(vis.ciel)draw(isNight?IM['02_ciel_nuit']:IM['01_ciel_jour'],0,0);if(vis.nuages){const cl=isNight?IM['06_nuages_wrap_nuit']:IM['05_nuages_wrap_jour'];for(let x=-off;x<768;x+=P)draw(cl,x,CY)}if(vis.mer){seaFrame(f,isNight?'nuit':'jour');ctx.drawImage(seaCv,0,D.manifest.sea_y)}const suf=isNight?'_n':'';for(const k of ['00_HERBE_NATIVE','01_FACES_NATIVE','02_RETOURS_NATIVE','03_COURONNES_NATIVE','04_PIEDS_NATIVE'])if(vis[k])draw(IM[vid+'_'+k+suf],0,0);requestAnimationFrame(render)}requestAnimationFrame(render);</script></html>'''
(R / 'apercu_falaises_proches_metano_v2.html').write_text(h.replace('__DATA__', json.dumps(data)), encoding='utf8')
print('gallery V2 written')
